"""Enumerative epsilon-almost-lossless encoder/decoder with detected failures.

Design rule + fixed-rate codec.  Encoding is O(k); decoding costs exactly
k + 2 elementary steps on a typical message, independent of |S|.
"""

from __future__ import annotations

import math
from typing import Dict, List, Optional, Sequence, Tuple

Bit = int
Word = List[Bit]


def to_bits(k: int, n: int) -> Word:
    """Little-endian k-bit expansion of n."""
    return [(n >> i) & 1 for i in range(k)]


def from_bits(w: Sequence[Bit]) -> int:
    """Read a little-endian bit list as a natural number."""
    return sum(b << i for i, b in enumerate(w))


def typical_set(p: Dict[str, float], eps: float) -> List[str]:
    """The (1 - eps)-quantile: the shortest heaviest prefix of mass >= 1 - eps."""
    ordered = sorted(p, key=lambda x: -p[x])
    mass, out = 0.0, []
    for x in ordered:
        if mass >= 1.0 - eps - 1e-15:
            break
        out.append(x)
        mass += p[x]
    return out


def design(p: Dict[str, float], eps: float) -> Tuple[List[str], int]:
    """Design rule: typical set S and rate parameter k = ceil(log2 |S|)."""
    s = typical_set(p, eps)
    k = max(0, math.ceil(math.log2(len(s)))) if s else 0
    return s, k


class EnumerativeCode:
    """Flag bit + k-bit index inside the typical set S; fixed rate k + 1."""

    def __init__(self, typical: Sequence[str], k: int) -> None:
        if len(typical) > 2 ** k:
            raise ValueError("typical set does not fit into 2^k indices")
        self.k = k
        self.table: List[str] = list(typical)
        self.index: Dict[str, int] = {x: i for i, x in enumerate(self.table)}

    def encode(self, x: str) -> Word:
        if x in self.index:
            return [1] + to_bits(self.k, self.index[x])
        return [0] + to_bits(self.k, 0)          # explicit failure marker

    def decode(self, w: Sequence[Bit]) -> Optional[str]:
        answer, _ = self.decode_instrumented(w)
        return answer

    def decode_instrumented(self, w: Sequence[Bit]) -> Tuple[Optional[str], int]:
        """Returns (answer or None, exact step count).  Cost k + 2 on S."""
        if not w or w[0] == 0:
            return (None, 1)
        rest = w[1:]
        cost = len(rest) + 2                      # bits, end marker, lookup
        idx = from_bits(rest)
        if idx < len(self.table):
            return (self.table[idx], cost)
        return (None, cost)

    def fail_prob(self, p: Dict[str, float]) -> float:
        return sum(v for x, v in p.items() if self.decode(self.encode(x)) != x)

"""Exhaustive-search decoding of an unstructured (random) codebook.

This is the decoder that Shannon's random-coding argument leaves you with:
the codebook has no arithmetic structure, so the only way to invert it is to
probe entries for equality with the received word.  Exact costs: |codebook|
probes in the worst case for every storage order, and n(n+1)/2 summed over
all n messages, i.e. (n+1)/2 on average.
"""

from __future__ import annotations

import random
from typing import Dict, List, Optional, Sequence, Tuple

Bit = int
Word = List[Bit]


def random_codebook(messages: Sequence[str], m: int, seed: int = 0
                    ) -> Dict[str, int]:
    """Draw a uniform codebook messages -> {0, ..., m-1}."""
    rng = random.Random(seed)
    return {x: rng.randrange(m) for x in messages}


def is_injective(codebook: Dict[str, int]) -> bool:
    return len(set(codebook.values())) == len(codebook)


def collision_prob_exact(q: int, m: int) -> float:
    """1 - m^{underline q} / m^q, the exact collision probability."""
    if q > m:
        return 1.0
    injective = 1.0
    for i in range(q):
        injective *= (m - i) / m
    return 1.0 - injective


def collision_prob_bound(q: int, m: int) -> float:
    """Birthday bound q(q-1)/(2m); attained with equality at q = 2."""
    return q * (q - 1) / (2 * m)


def scan_decode(entries: Sequence[Tuple[str, int]], received: int
                ) -> Tuple[Optional[str], int]:
    """Left-to-right equality probes; returns (answer, number of probes)."""
    probes = 0
    for name, value in entries:
        probes += 1
        if value == received:
            return (name, probes)
    return (None, probes)


def scan_cost_profile(entries: Sequence[Tuple[str, int]]) -> Tuple[int, float, int]:
    """Returns (worst-case probes, average probes, total probes)."""
    costs = [scan_decode(entries, value)[1] for _, value in entries]
    return (max(costs), sum(costs) / len(costs), sum(costs))
